contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a) public {
        c.setOwner(a); if (__ESBMC_reverted()) return;
        address current = c.owner(); if (__ESBMC_reverted()) return;
        require(current == a);

        bool reverted;
        c.setOwner(current); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && c.owner() == current);
    }

    receive() external payable {}
}

