pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address a) internal {
        try c.setOwner(a) {} catch { return; }
        address current;
        try c.owner() returns (address __r) { current = __r; } catch { return; }
        a = current;
        bool reverted;
        try c.setOwner(current) { reverted = false; }
        catch { reverted = true; }
        assertTrue(!reverted && c.owner() == current);
    }

    function testFuzz_run(address a) public {
        _run(a);
    }

    receive() external payable {}
}
